export const title = "TCP Communication";
export const html = "<h1>TCP Communication</h1>\n      <hr class=\"rule\" />\n\n<p>When an application event occurs, you can connect to a TCP server and transmit data.</p>\n\n<p>A TCP Communication action can be added from the action settings screen.</p>\n<div class=\"figure\" style=\"max-width:340px;\">\n<div class=\"app-panel\">\n  <div class=\"form-grid\" style=\"grid-template-columns:80px 1fr;\">\n    <span>Action Type</span><select disabled><option>TCP</option></select>\n  </div>\n</div>\n</div>\n\n<h2>Server Settings</h2>\n<div class=\"figure\" style=\"max-width:340px;\">\n<div class=\"app-panel\">\n  <div class=\"form-grid\" style=\"grid-template-columns:60px 1fr;font-size:12.5px;\">\n    <span>Host</span><input value=\"192.168.101.11\" disabled>\n    <span>Port</span><input value=\"1234\" disabled>\n  </div>\n</div>\n</div>\n<p>Sets the target server's IP address and port.</p>\n\n<h2>Action Flow</h2>\n<div class=\"figure\" style=\"max-width:340px;\">\n<div class=\"app-panel\">\n  <div class=\"form-grid\" style=\"grid-template-columns:90px 1fr;font-size:12.5px;\">\n    <span>Action Flow</span><select disabled><option>Send, Close</option><option>Send, Recv, Close</option></select>\n  </div>\n</div>\n</div>\n\n<h3 style=\"margin-top:24px;\">Send, Close</h3>\n<p>Connects to the server, sends the preconfigured message, and closes the connection.</p>\n\n<h3 style=\"margin-top:24px;\">Send, Recv, Close</h3>\n<p>Connects to the server, sends the preconfigured message, waits to receive a response message, then closes the connection. The response timeout is 3 seconds.</p>\n\n<h2>Message Type</h2>\n<div class=\"figure\" style=\"max-width:340px;\">\n<div class=\"app-panel\">\n  <div class=\"form-grid\" style=\"grid-template-columns:100px 1fr;font-size:12.5px;\">\n    <span>Message Type</span><select disabled><option>UTF-8 Characters</option><option>Hex Codes</option></select>\n  </div>\n</div>\n</div>\n<p>The message type can be set to one of two types.</p>\n<p><strong>UTF-8</strong> can be used to configure a general text-format message, encoded as UTF-8.</p>\n<p><strong>Hex Codes</strong> is a way of representing binary data values in hexadecimal.</p>\n\n<h3 style=\"margin-top:24px;\">UTF-8</h3>\n<p>The UTF-8 format can be set using tokens and a template. See the configuration example below.</p>\n\n<div class=\"figure\">\n<div class=\"app-panel\" style=\"max-width:520px;\">\n  <div class=\"form-grid\" style=\"grid-template-columns:120px 1fr auto;font-size:12.5px;\">\n    <span>String Construction</span><select disabled><option>Use template</option></select><span class=\"btn small primary\">Use</span>\n    <span></span><select disabled><option>Select to add tokens</option></select><span class=\"btn small primary\">Add</span>\n  </div>\n  <div class=\"section-label\">Editable Box</div>\n  <div style=\"background:#fff;border:1px solid var(--border);border-radius:6px;padding:10px;font-family:monospace;font-size:12.5px;\">CH{{CH}} - {{EVENT NAME}} - {{TIMESTAMP}}</div>\n  <div class=\"section-label\">Message Example</div>\n  <div style=\"background:#fff;border:1px solid var(--border);border-radius:6px;padding:10px;font-family:monospace;font-size:12.5px;\">CH3 - My Event Name - 1561961100.123456</div>\n</div>\n<figcaption>UTF-8 message construction example</figcaption>\n</div>\n\n<h3 style=\"margin-top:24px;\">Hex Codes</h3>\n<p>Token values can't be used in Hex Codes format, but you can set raw data using hexadecimal values. See the configuration example below.</p>\n<div class=\"figure\">\n<div class=\"app-panel\" style=\"max-width:520px;\">\n  <div class=\"section-label\">Hex Bytes</div>\n  <div style=\"background:#fff;border:1px solid var(--border);border-radius:6px;padding:10px;font-family:monospace;font-size:12.5px;\">01 02 0A FF</div>\n</div>\n<figcaption>Hex Codes message example</figcaption>";
